package com.zxl.zxlaiagent.security;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import java.sql.*;
import java.time.*;
import java.util.UUID;
public final class AuthenticationService {
 private static final BCryptPasswordEncoder PASSWORDS=new BCryptPasswordEncoder(12);
 private static final String DUMMY_HASH=PASSWORDS.encode("synthetic-dummy-password-for-timing");
 private final SecurityDatabase db; private final BCryptPasswordEncoder passwords=PASSWORDS;
 public AuthenticationService(SecurityDatabase db){this.db=db;}
 public record LoginSession(AuthenticatedActor actor,String credential,String csrfToken,Instant expiresAt){@Override public String toString(){return "LoginSession[redacted]";}}
 /** Explicit offline provisioning only; never invoked automatically or from a public controller. */
 public void provision(String subject,String login,String password,String tenant,String role){if(!validId(subject)||!validId(login)||!validId(tenant)||!validPassword(password)||!("employee".equals(role)||"knowledge-maintainer".equals(role)))throw new SecurityFailure("INVALID_PROVISIONING_INPUT",400);String hash=passwords.encode(password);db.tx(c->{try(var s=SecurityDatabase.statement(c,"INSERT INTO tenant(tenant_id) VALUES (?) ON CONFLICT DO NOTHING",tenant)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO subject(subject_id,login_name,password_hash) VALUES (?,?,?)",subject,login,hash)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO membership(tenant_id,subject_id,role) VALUES (?,?,?)",tenant,subject,role)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO authorization_epoch(tenant_id,subject_id) VALUES (?,?)",tenant,subject)){s.executeUpdate();}return null;});}
 public LoginSession login(String login,String password,String tenant){if(!validId(login)||!validId(tenant)||!validPassword(password))throw invalid();return db.tx(c->{String subject,hash;try(var s=SecurityDatabase.statement(c,"SELECT subject_id,password_hash FROM subject WHERE login_name=? AND status='ACTIVE' FOR UPDATE",login);var r=s.executeQuery()){if(r.next()){subject=r.getString(1);hash=r.getString(2);}else{subject=null;hash=DUMMY_HASH;}}boolean matches=passwords.matches(password,hash);if(!matches||subject==null)throw invalid();try(var s=SecurityDatabase.statement(c,"SELECT 1 FROM membership m JOIN tenant t USING(tenant_id) WHERE m.subject_id=? AND m.tenant_id=? AND m.status='ACTIVE' AND t.status='ACTIVE'",subject,tenant);var r=s.executeQuery()){if(!r.next())throw invalid();}
 lockEpoch(c,new ActorRef(subject,tenant,"pending-login",1));
 String id=UUID.randomUUID().toString(),credential=CredentialDigests.random(),csrf=CredentialDigests.random();Instant expiry=Instant.now().plus(Duration.ofHours(8));
 try(var s=SecurityDatabase.statement(c,"UPDATE auth_session SET revoked_at=now(),version=version+1 WHERE session_id IN (SELECT session_id FROM auth_session WHERE subject_id=? AND tenant_id=? AND revoked_at IS NULL ORDER BY created_at DESC,session_id DESC OFFSET 4)",subject,tenant)){s.executeUpdate();}
 try(var s=SecurityDatabase.statement(c,"INSERT INTO auth_session(session_id,credential_hash,subject_id,tenant_id,expires_at,csrf_hash) VALUES (?,?,?,?,?,?)",id,CredentialDigests.hash(credential),subject,tenant,Timestamp.from(expiry),CredentialDigests.hash(csrf))){s.executeUpdate();}
 return new LoginSession(resolve(c,new ActorRef(subject,tenant,id,1)),credential,csrf,expiry);});}
 public AuthenticatedActor authenticate(String credential){if(credential==null||credential.length()>256)throw invalid();return db.tx(c->{try(var s=SecurityDatabase.statement(c,"SELECT subject_id,tenant_id,session_id,version FROM auth_session WHERE credential_hash=?",CredentialDigests.hash(credential));var r=s.executeQuery()){if(!r.next())throw invalid();return resolve(c,new ActorRef(r.getString(1),r.getString(2),r.getString(3),r.getLong(4)));}});}
 public AuthenticatedActor resolve(ActorRef ref){return db.tx(c->resolve(c,ref));}
 static AuthenticatedActor resolve(Connection c,ActorRef ref)throws SQLException{validateRef(ref);lockEpoch(c,ref);try(var s=SecurityDatabase.statement(c,"SELECT s.version,m.role,e.version FROM authorization_epoch e JOIN membership m USING(tenant_id,subject_id) JOIN auth_session s USING(tenant_id,subject_id) JOIN subject u USING(subject_id) JOIN tenant t USING(tenant_id) WHERE s.session_id=? AND s.subject_id=? AND s.tenant_id=? AND s.version=? AND s.revoked_at IS NULL AND m.status='ACTIVE' AND u.status='ACTIVE' AND t.status='ACTIVE' FOR UPDATE OF e,s,m",ref.sessionId(),ref.subjectId(),ref.tenantId(),ref.authenticationVersion());var r=s.executeQuery()){if(!r.next())throw invalid();var actor=new AuthenticatedActor(ref.subjectId(),ref.tenantId(),ref.sessionId(),r.getLong(1),r.getString(2),r.getLong(3));if(!sessionNotExpired(c,ref))throw invalid();return actor;}}
 public void validateCsrf(ActorRef ref,String csrf){db.tx(c->{resolve(c,ref);try(var s=SecurityDatabase.statement(c,"SELECT csrf_hash FROM auth_session WHERE session_id=?",ref.sessionId());var r=s.executeQuery()){r.next();if(!CredentialDigests.matches(csrf,r.getString(1)))throw new SecurityFailure("CSRF_INVALID",403);}return null;});}
 public String rotateCsrf(ActorRef ref){return db.tx(c->{resolve(c,ref);String token=CredentialDigests.random();try(var s=SecurityDatabase.statement(c,"UPDATE auth_session SET csrf_hash=? WHERE session_id=?",CredentialDigests.hash(token),ref.sessionId())){s.executeUpdate();}return token;});}
 public String loginName(ActorRef ref){return db.tx(c->{resolve(c,ref);try(var s=SecurityDatabase.statement(c,"SELECT login_name FROM subject WHERE subject_id=?",ref.subjectId());var r=s.executeQuery()){r.next();return r.getString(1);}});}
 public void revoke(ActorRef ref){db.tx(c->{lockEpoch(c,ref);try(var s=SecurityDatabase.statement(c,"UPDATE auth_session SET revoked_at=now(),version=version+1 WHERE session_id=? AND subject_id=? AND tenant_id=?",ref.sessionId(),ref.subjectId(),ref.tenantId())){s.executeUpdate();}return null;});}
 static void lockEpoch(Connection c,ActorRef ref)throws SQLException{validateRef(ref);try(var s=SecurityDatabase.statement(c,"SELECT version FROM authorization_epoch WHERE tenant_id=? AND subject_id=? FOR UPDATE",ref.tenantId(),ref.subjectId());var r=s.executeQuery()){if(!r.next())throw invalid();}}
 /** Called only after epoch and session locks have been acquired; a new SQL statement observes the actual DB clock. */
 static boolean sessionNotExpired(Connection c,ActorRef ref)throws SQLException{try(var s=SecurityDatabase.statement(c,"SELECT expires_at>clock_timestamp() FROM auth_session WHERE session_id=?",ref.sessionId());var r=s.executeQuery()){return r.next()&&r.getBoolean(1);}}
 static boolean validId(String value){return value!=null&&!value.isBlank()&&value.length()<=150&&value.chars().noneMatch(Character::isISOControl);}
 static boolean validPassword(String value){return value!=null&&!value.isBlank()&&value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=72;}
 static void validateRef(ActorRef ref){if(ref==null||!validId(ref.subjectId())||!validId(ref.tenantId())||!validId(ref.sessionId())||ref.sessionId().length()>80||ref.authenticationVersion()<1)throw invalid();}
 static SecurityFailure invalid(){return new SecurityFailure("UNAUTHENTICATED",401);}
}
